namespace Mori {
 internal static class VideoBrowserTests {
  static List<Asset> Visible(MainWindow main){return (List<Asset>)typeof(MainWindow).GetField("visible",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(main);}
  static void Refresh(MainWindow main){typeof(MainWindow).GetMethod("Refresh",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(main,new object[]{false});}
  static void Pump(int milliseconds){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(milliseconds)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
  static bool Hit(FrameworkElement root,FrameworkElement control){
   var point=control.TranslatePoint(new Point(control.ActualWidth/2,control.ActualHeight/2),root);DependencyObject target=null;
   VisualTreeHelper.HitTest(root,node=>{var ui=node as UIElement;return ui!=null&&(ui.Visibility!=Visibility.Visible||!ui.IsHitTestVisible)?HitTestFilterBehavior.ContinueSkipSelfAndChildren:HitTestFilterBehavior.Continue;},result=>{target=result.VisualHit;return HitTestResultBehavior.Stop;},new PointHitTestParameters(point));
   bool found=false;for(var node=target;node!=null;node=MainWindow.SelectionParent(node)){var ui=node as UIElement;if(ui!=null&&(ui.Visibility!=Visibility.Visible||!ui.IsHitTestVisible||!ui.IsEnabled))return false;if(ReferenceEquals(node,control))found=true;}return found;
  }
  public static void Run(string output,Action<bool,string> check){
   Directory.CreateDirectory(output);var app=Application.Current??new Application();var previous=app.ShutdownMode;app.ShutdownMode=ShutdownMode.OnExplicitShutdown;
   try{
    var state=new VideoPlayback();check(!state.Ready,"video progress disabled before finite duration is known");state.Open(double.NaN);check(!state.Ready,"indeterminate duration never enables seek");state.Open(12);state.Seek(50);check(state.Position==12,"seek clamps to duration");state.Seek(-5);check(state.Position==0,"seek clamps to start");state.Seek(double.PositiveInfinity);check(state.Position==0,"invalid seek is safe");
    state.Seeking=true;state.Seek(8);state.Tick(2);check(state.Position==8,"playback timer cannot fight user's drag");state.Seeking=false;state.Tick(9);check(state.Position==9,"playback timer follows media after seeking");state.Playing=false;state.End();check(!state.Playing&&state.Position==0,"loop reset preserves paused state");check(VideoPlayback.Time(65)=="01:05"&&VideoPlayback.Time(3661)=="1:01:01","video timestamps support short and long clips");
    check(MiddleScroll.Speed(12,500)==0&&MiddleScroll.Speed(-11,500)==0,"middle-scroll dead zone prevents accidental drift");check(MiddleScroll.Speed(100,500)>MiddleScroll.Speed(30,500)&&MiddleScroll.Speed(-100,500)==-MiddleScroll.Speed(100,500),"middle-scroll speed follows pointer distance and direction");check(MiddleScroll.Speed(100000,500)==3000&&MiddleScroll.Speed(double.NaN,500)==0,"middle-scroll speed is bounded and rejects invalid distance");
    var viewport=new ScrollViewer{Content=new Border{Height=2000},Height=200,Width=300};viewport.Measure(new Size(300,200));viewport.Arrange(new Rect(0,0,300,200));viewport.UpdateLayout();check(MiddleScroll.ScrollTarget((Border)viewport.Content)==viewport,"middle-scroll resolves underlying scrollable pane");check(MiddleScroll.ScrollTarget(new TextBox())==null&&MiddleScroll.ScrollTarget(new Slider())==null,"middle-scroll leaves text selection and sliders alone");var window=new Window();var middle=new MiddleScroll(window);middle.Stop();check(!middle.Active,"middle-scroll has no active timer/session at rest");window.Close();
    foreach(double width in new[]{180.0,242,484,720,1024}){double card=MainWindow.BookmarkCardWidth(width);int columns=Math.Max(1,(int)(width/242));check(card>=100&&(card+10)*columns<=width,"folder cards including gaps fit width "+width);}
    using(var lib=new Library(Path.Combine(output,"library"))){
     string root=lib.CreateFolder("设计参考","",true),child=lib.CreateFolder("产品灵感",root,true);var a=lib.ImportBookmark("https://example.com/root","根层网页",root).Item;var b=lib.ImportBookmark("https://example.com/nested","子层网页",child).Item;var loose=lib.ImportBookmark("https://example.com/loose","未分类","").Item;var trash=lib.ImportBookmark("https://example.com/trash","回收站",child).Item;lib.Trash(new[]{trash.Id},true);
     var memberships=lib.Db.Query("SELECT asset,folder FROM memberships");memberships.Add(new Dictionary<string,string>{{"asset",b.Id},{"folder",root}});var counts=MainWindow.BookmarkCounts(lib.Folders(true),memberships,new HashSet<string>(lib.All().Where(x=>!x.Deleted).Select(x=>x.Id)));check(counts[root]==2&&counts[child]==1,"folder counts deduplicate descendants and exclude trash");
     var main=new MainWindow(lib){PreviewMode=true};try{main.SetSection("bookmarks");check(Visible(main).Single().Id==loose.Id,"folder-first home shows only loose URLs, never flattens imported hierarchy");var folders=(WrapPanel)main.Window.FindName("BookmarkFolderList");check(folders.Children.Count==1&&((Button)folders.Children[0]).Height==88,"home uses large readable folder cards");
      main.RequestNavigate(root);check(Visible(main).Single().Id==a.Id,"folder browsing shows direct URLs only");check(((TextBlock)main.Window.FindName("ViewCount")).Text=="2 个网址（含子文件夹）","folder heading counts descendants and explains its scope");((TextBox)main.Window.FindName("Search")).Text="子层";Refresh(main);check(Visible(main).Single().Id==b.Id&&folders.Children.Count==0,"folder search includes descendants without redundant folder cards");main.RequestNavigate("all");check(Visible(main).Count==3,"all-URLs view remains explicitly available");main.SetSection("bookmarks");lib.MoveBookmarks(new[]{loose.Id},root);Refresh(main);check(Visible(main).Count==0&&((StackPanel)main.Window.FindName("Empty")).Visibility==Visibility.Collapsed,"folder-only homepage does not show misleading empty-library message");
      string[] labeledCommands={"HomeAdd","All","Bookmarks","Trash","Settings"};
      foreach(string id in labeledCommands){var button=(Button)main.Window.FindName(id);string label=button.Content as string;check(!string.IsNullOrWhiteSpace(label)&&label.Length>1&&UiIcons.GetGlyph(button).Length==1&&button.Visibility==Visibility.Visible&&button.Focusable,"visible command keeps a readable label and icon: "+id);}
      var settings=(Button)main.Window.FindName("Settings");check(Convert.ToString(settings.Content)=="设置"&&UiIcons.GetGlyph(settings)=="\uE713"&&Convert.ToString(settings.ToolTip).Contains("设置"),"sidebar settings keeps its readable label, standard gear and hover explanation");
      foreach(var command in new[]{new[]{"More","\uE712","更多操作"},new[]{"HomeView","\uE8A9","显示选项"},new[]{"HomeNavigationToggle","\uE700","导航栏"}}){var button=(Button)main.Window.FindName(command[0]);check(Convert.ToString(button.Content)==command[1]&&System.Windows.Automation.AutomationProperties.GetName(button).Contains(command[2])&&!string.IsNullOrWhiteSpace(Convert.ToString(button.ToolTip))&&button.Visibility==Visibility.Visible&&button.Focusable,"icon-only command retains its visible glyph, accessible and hover labels: "+command[0]);}
      check(((StackPanel)main.Window.FindName("LegacyHomeActions")).Visibility==Visibility.Collapsed&&((ComboBox)main.Window.FindName("MediaFilter")).Visibility==Visibility.Collapsed,"legacy import/export/type controls do not form a second visible toolbar");
      var addMenu=main.CreateHomeAddMenu();var addActions=addMenu.Items.OfType<MenuItem>().ToArray();check(addActions.Select(item=>Convert.ToString(item.Header)).SequenceEqual(new[]{"收藏网址…","导入浏览器书签…","粘贴收藏"})&&addActions.All(item=>item.IsEnabled&&item.Focusable)&&addActions[1].InputGestureText=="Ctrl+O"&&addActions[2].InputGestureText=="Ctrl+V","visible Add entry offers bookmark-specific commands and their keyboard shortcuts");
      check(((Button)main.Window.FindName("HomeTypePicker")).Visibility==Visibility.Collapsed&&main.CreateHomeTypeMenu().Items.Count==0,"bookmark browsing does not expose irrelevant material-type actions");
      check(UiIcons.ForMenu("永久删除…")=="\uE74D"&&UiIcons.ForMenu("撤销 移动网址")=="\uE7A7"&&UiIcons.ForMenu(null)=="","context icons distinguish destructive/undo commands safely");
      var body=(FrameworkElement)main.Window.Content;main.Window.Content=null;body.Resources.MergedDictionaries.Add(main.Window.Resources);foreach(string theme in new[]{"light","dark"}){Theme.Set(theme);body.Width=1040;body.Height=680;body.Measure(new Size(1040,680));body.Arrange(new Rect(0,0,1040,680));body.UpdateLayout();var search=(TextBox)main.Window.FindName("Search");check(search.ActualWidth>=150&&Hit(body,search),"toolbar retains usable, reachable search at minimum width / "+theme);foreach(string id in labeledCommands.Concat(new[]{"More","HomeView","HomeNavigationToggle"})){var button=(Button)main.Window.FindName(id);check(button.ActualWidth>=24&&button.ActualHeight>=24&&Hit(body,button),"visible home command remains reachable at minimum width / "+theme+" / "+id);}}
      check(lib.All().Count==4&&lib.Folders(true).Count==2&&lib.Db.Query("PRAGMA foreign_key_check").Count==0,"new browser controls preserve fixture URLs and folder relationships");
     }finally{main.Window.Close();ThumbnailImage.CurrentLibrary=null;}
    }
    using(var lib=new Library(Path.Combine(output,"browser-ui-library"))){string root=lib.CreateFolder("Chrome 导入书签","",true);string[] labels={"工业设计参考","产品与结构灵感","摄影和配色","工作常用工具","素材资源","稍后阅读"};for(int i=0;i<labels.Length;i++){string folder=lib.CreateFolder(labels[i],root,true);for(int j=1;j<=30;j++)lib.ImportBookmark("https://example.com/demo/"+i+"/"+j,labels[i]+" "+j.ToString("D2"),folder);}lib.ImportBookmark("https://example.org/loose","临时未分类收藏","");check(lib.All().Count==181&&lib.Folders(true).Count==7,"large synthetic bookmark fixture retains six original folders for visual and scrolling checks");}
    string fixture=Environment.GetEnvironmentVariable("MORI_TEST_VIDEO");if(!string.IsNullOrEmpty(fixture))RealVideo(fixture,output,check);
   }finally{app.ShutdownMode=previous;}
  }
  static void RealVideo(string file,string output,Action<bool,string> check){
   check(File.Exists(file),"real generated video fixture exists");byte[] original=File.ReadAllBytes(file);int width,height;var clock=Stopwatch.StartNew();var poster=VideoThumbnail.Render(file,out width,out height);check(poster!=null&&poster.PixelWidth<=512&&poster.PixelHeight<=512&&width==640&&height==360,"Windows extracts bounded real MP4 poster and native dimensions / "+width+"x"+height+" / "+VideoThumbnail.LastFailure);
   using(var lib=new Library(Path.Combine(output,"video-library"))){var item=lib.Import(file,"","时间标尺测试","","","").Item;lib.BuildThumbnail(item);check(File.Exists(lib.ThumbnailPath(item))&&item.Width==640&&item.Height==360,"video import caches poster and indexes dimensions");DateTime saved=File.GetLastWriteTimeUtc(lib.ThumbnailPath(item));lib.BuildThumbnail(item);check(saved==File.GetLastWriteTimeUtc(lib.ThumbnailPath(item)),"cached video poster is reused without decoding");check(original.SequenceEqual(File.ReadAllBytes(lib.FullPath(item))),"video thumbnail never alters original video bytes");}
   string broken=Path.Combine(output,"broken.mp4");File.WriteAllText(broken,"not a video");check(VideoThumbnail.Render(broken,out width,out height)==null,"invalid video never caches a file-type icon as its poster");clock.Restart();check(VideoThumbnail.Render(broken,out width,out height)==null&&clock.ElapsedMilliseconds<100,"unsupported video failure is cached to avoid repeated decoding");
   var player=new VideoPlayer(file);var host=new Grid{Width=640,Height=430};host.Children.Add(player.Root);var source=new HwndSource(new HwndSourceParameters("Mori isolated media regression"){Width=640,Height=430,WindowStyle=0});source.RootVisual=host;host.Measure(new Size(640,430));host.Arrange(new Rect(0,0,640,430));host.UpdateLayout();player.Start();clock.Restart();while(!player.State.Ready&&!player.Failed&&clock.ElapsedMilliseconds<8000)Pump(100);
   try{check(player.State.Ready&&!player.Failed&&Math.Abs(player.State.Duration-12)<.1,"real MediaElement opens 12-second MP4");player.SetVolume(.28);check(Math.Abs(player.Media.Volume-.28)<.0001,"real native decoder receives chosen volume");player.ToggleMute();check(player.Media.Volume==0&&Math.Abs(player.Sound.Level-.28)<.0001,"real native decoder mute retains slider level");player.ToggleMute();check(Math.Abs(player.Media.Volume-.28)<.0001&&!player.Sound.Muted,"real native decoder restores chosen volume");player.Toggle();player.Seek(8);Pump(500);check(!player.State.Playing&&!player.TimerRunning&&Math.Abs(player.Media.Position.TotalSeconds-8)<.3,"paused seek lands at requested time without resuming");player.BeginSeek();player.State.Seek(3);player.EndSeek();Pump(300);check(!player.State.Playing&&Math.Abs(player.Media.Position.TotalSeconds-3)<.3,"mouse-seek state preserves pause and commits selected time");player.Toggle();Pump(700);check(player.State.Playing&&player.TimerRunning&&player.Media.Position.TotalSeconds>3.3,"play resumes from new seek point");player.Seek(11.8);Pump(1000);check(player.State.Playing&&player.Media.Position.TotalSeconds<3,"video end loops back to first frame");player.SetVisible(false);check(!player.TimerRunning,"hidden video suspends progress timer and playback");player.SetVisible(true);check(player.TimerRunning,"visible playing video resumes timer");}finally{player.Dispose();source.Dispose();}check(!player.TimerRunning&&player.Media.Source==null,"closing video releases decoder and progress timer");
  }
 }
}
